-- JSON/JSONB container width is bounded by statement memory, not the former
-- 1,024-element staging arrays, 64-level depth cap, 256-step jsonpath chains,
-- or 64 KiB text buffers. This file runs unchanged on PostgreSQL 18.

CREATE TABLE json_value_width(id integer PRIMARY KEY, doc jsonb, legacy json);

-- 5,000-element arrays and 2,000-member objects, through both the jsonb tree
-- and the verbatim json text path
INSERT INTO json_value_width
SELECT 1, jsonb_agg(g ORDER BY g), json_agg(g ORDER BY g) FROM generate_series(1, 5000) g;
INSERT INTO json_value_width
SELECT 2,
       (SELECT jsonb_object_agg('k' || g, g) FROM generate_series(1, 2000) g),
       (SELECT json_object_agg('k' || g, g) FROM generate_series(1, 2000) g);

SELECT jsonb_array_length(doc), json_array_length(legacy) FROM json_value_width WHERE id = 1;
SELECT (SELECT count(*) FROM jsonb_each(doc)) FROM json_value_width WHERE id = 2;
SELECT doc->'k1999', legacy->>'k2000' FROM json_value_width WHERE id = 2;
SELECT length(('[' || '"' || repeat('é', 40000) || '\n"' || ']')::json ->> 0);
SELECT length(jsonb_pretty(jsonb_build_array(repeat('a', 70000))));
