-- PostgreSQL resolves the json and jsonb function families strictly: the
-- cross-family forms below are 42883 on both implementations
SELECT jsonb_array_length('[1]'::json);
SELECT jsonb_array_length(NULL::json);
SELECT json_array_length('[1]'::jsonb);
SELECT json_array_length(NULL::jsonb);
SELECT jsonb_typeof('1'::json);
SELECT json_typeof('1'::jsonb);
SELECT jsonb_pretty('[1]'::json);
SELECT jsonb_set('{}'::json, '{a}', '1');
SELECT jsonb_insert('[]'::json, '{0}', '1');
SELECT jsonb_strip_nulls('{}'::json);
SELECT json_strip_nulls('{}'::jsonb);
SELECT jsonb_path_query_first('[1]'::json, '$[*]');
SELECT * FROM jsonb_each('{"a":1}'::json);
SELECT * FROM json_each('{"a":1}'::jsonb);
SELECT * FROM jsonb_array_elements('[1]'::json);
SELECT * FROM json_array_elements('[1]'::jsonb);
SELECT * FROM jsonb_object_keys('{"a":1}'::json);
SELECT * FROM json_object_keys('{"a":1}'::jsonb);
SELECT * FROM jsonb_to_record('{"a":1}'::json) AS x(a int);
SELECT * FROM json_to_record('{"a":1}'::jsonb) AS x(a int);
SELECT * FROM jsonb_populate_record(null::json_value_width, '{"id":1}'::json);
SELECT * FROM json_populate_record(null::json_value_width, '{"id":1}'::jsonb);
SELECT '{"a":1}'::jsonb || '{"b":2}'::json;
SELECT '{"a":1}'::json - 'a';
SELECT '{"a":1}'::json #- '{a}';
SELECT '{"a":1}'::json ? 'a';

-- cleanup
DROP TABLE json_value_width;
